short SwapEndian ( short );long SwapEndian ( long );short SwapEndian ( short n ){	union swapper	{		short a;		char b[2];	} swap1, swap2;	swap1.a = n;	swap2.b[0] = swap1.b[1];	swap2.b[1] = swap1.b[0];		return (swap2.a);}long SwapEndian ( long n ){	union swapper	{		long a;		char b[4];	} swap1, swap2;	swap1.a = n;	swap2.b[0] = swap1.b[3];	swap2.b[1] = swap1.b[2];	swap2.b[2] = swap1.b[1];	swap2.b[3] = swap1.b[0];		return (swap2.a);}